22.10.17.3.1 General [func.wrap.func.general]
🔗
namespace std {
  template<class R, class... ArgTypes>
  class function<R(ArgTypes...)> {
  public:
    using result_type = R;
    // [func.wrap.func.con], construct/copy/destroy
    function() noexcept;
    function(nullptr_t) noexcept;
    function(const function&);
    function(function&&) noexcept;
    template<class F> function(F&&);
    function& operator=(const function&);
    function& operator=(function&&);
    function& operator=(nullptr_t) noexcept;
    template<class F> function& operator=(F&&);
    template<class F> function& operator=(reference_wrapper<F>) noexcept;
    ~function();
    // [func.wrap.func.mod], function modifiers
    void swap(function&) noexcept;
    // [func.wrap.func.cap], function capacity
    explicit operator bool() const noexcept;
    // [func.wrap.func.inv], function invocation
    R operator()(ArgTypes...) const;
    // [func.wrap.func.targ], function target access
    const type_info& target_type() const noexcept;
    template<class T>       T* target() noexcept;
    template<class T> const T* target() const noexcept;
  };
  template<class R, class... ArgTypes>
    function(R(*)(ArgTypes...)) -> function<R(ArgTypes...)>;
  template<class F> function(F) -> function<see below>;
}
1
#
The function class template provides polymorphic wrappers that
generalize the notion of a function pointer.
 Wrappers can store, copy,
and call arbitrary callable objects ([func.def]), given a call
signature ([func.def]).
2
#
The function class template is a call
wrapper ([func.def]) whose call signature ([func.def])
is R(ArgTypes...).
